import type { SVGProps } from "react";

// Real brand SVGs for the nine major job platforms shown in the marquee.
// Most map to sources Job Board pulls postings from; Handshake is included
// as a recognized college-recruiting brand even though we don't scrape it.
//
// Each entry exposes:
//   name         — display label
//   Svg          — inline React SVG component (renders at parent-controlled
//                  height; width is derived from the viewBox so brand
//                  proportions are preserved)
//   brandColor   — the official primary brand color, used to tint the
//                  separate name label (and as the SVG fill where the mark
//                  is monochrome). For multi-color marks the colors are
//                  baked into the SVG paths themselves.
//   wordmarkOnly — when true the SVG already contains the company name in
//                  its design, so the renderer skips the separate text label
//                  to avoid the name appearing twice.
//
// Sources:
//   LinkedIn     — Wikimedia Commons (LinkedIn_icon.svg)
//   Greenhouse   — simple-icons (siGreenhouse)
//   Indeed       — simple-icons (siIndeed)
//   Glassdoor    — simple-icons (siGlassdoor)
//   Simplify     — simplify.jobs official logo asset
//   ZipRecruiter — worldvectorlogo (ziprecruiter-blacktext.svg, official)
//   Workday      — worldvectorlogo (workday-logo.svg, official)
//   Ashby        — geometric approximation (their brand assets are gated
//                  behind Brandfetch's paid API; no public SVG download)
//   Handshake    — joinhandshake.com/handshake-app-icon.svg (official app
//                  icon: neon-yellow rounded square with dark teal "H")
//
// Trademark note: these are trademarks of their respective owners, used here
// at low opacity for decorative reference on a personal-use page; not
// claiming affiliation or endorsement.

type LogoSvg = (props: SVGProps<SVGSVGElement>) => React.ReactElement;

export type CompanyLogo = {
  name: string;
  Svg: LogoSvg;
  brandColor: string;
  wordmarkOnly?: boolean;
};

